<!DOCTYPE html>
<html lang="ro">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="robots" content="noindex, nofollow">
  <meta name="theme-color" content="#061a15">
  <title>Biletele mele — Nordvale</title>
  <meta name="description" content="Bilete active, viitoare și utilizate în contul Nordvale.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet">
  <style>
    :root{
      --pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;
      --acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;--ink:#16231e;
      --line:rgba(9,37,29,.12);--shadow:0 28px 80px -48px rgba(6,26,21,.62);--card-shadow:0 20px 54px -38px rgba(6,26,21,.48)
    }
    *{box-sizing:border-box}html{background:var(--oat);scroll-behavior:smooth}body{margin:0;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:"DM Sans",sans-serif;text-rendering:optimizeLegibility}button,input{font:inherit}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}[hidden]{display:none!important}::selection{background:var(--acid);color:var(--pine-950)}
    .shell{width:min(1460px,calc(100% - 32px));margin-inline:auto}.grain{position:relative}.grain:after{content:"";position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.07;mix-blend-mode:soft-light;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='.56'/%3E%3C/svg%3E")}.topo{background-image:radial-gradient(circle at 14% 16%,rgba(223,252,98,.14),transparent 20%),radial-gradient(circle at 88% 20%,rgba(242,123,74,.13),transparent 16%),url("data:image/svg+xml,%3Csvg width='760' height='760' viewBox='0 0 760 760' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.06' stroke-width='1.05'%3E%3Cpath d='M74 206c43-106 166-167 278-119 89 39 107 147 52 218-51 66-143 59-194 124-58 73-49 188-142 228-91 38-186-37-164-132 20-89 111-106 122-190 8-57-5-88 48-129Z'/%3E%3Cpath d='M493 410c57-79 161-89 227-18 60 64 24 169-55 198-71 26-142-17-201 28-52 40-62 123-129 129-74 6-126-73-84-135 38-56 112-39 155-92 35-43 39-79 87-110Z'/%3E%3C/g%3E%3C/svg%3E");background-size:auto,auto,760px 760px}

    .site-header{position:sticky;top:0;z-index:50;padding:12px 0;background:linear-gradient(180deg,rgba(240,236,223,.94),rgba(240,236,223,.76),transparent)}
    .nav{display:flex;align-items:center;gap:16px;padding:10px 12px 10px 16px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:rgba(6,26,21,.87);box-shadow:0 24px 70px -46px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%);color:#fff}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border:1px solid rgba(223,252,98,.42);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid)}.brand-copy{min-width:0;line-height:1}.brand-copy strong{display:block;font-family:"Fraunces",serif;font-size:18px;font-weight:600;letter-spacing:-.02em}.brand-copy span{display:block;margin-top:5px;color:rgba(255,255,255,.5);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap}.main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600;transition:.2s ease}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.nav-icon,.menu-btn{display:grid;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff;cursor:pointer}.nav-icon{position:relative}.nav-icon:after{content:"";position:absolute;top:8px;right:8px;width:7px;height:7px;border:2px solid var(--pine-900);border-radius:50%;background:var(--ember)}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none}

    .layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:24px;padding:18px 0 72px}.sidebar{position:sticky;top:92px;align-self:start;padding:18px;border:1px solid var(--line);border-radius:26px;background:rgba(255,253,246,.78);box-shadow:var(--card-shadow);backdrop-filter:blur(18px)}.profile-mini{display:flex;align-items:center;gap:12px;padding:8px 8px 20px;border-bottom:1px solid var(--line)}.avatar{display:grid;place-items:center;width:50px;height:50px;border-radius:18px;background:var(--pine-900);color:var(--acid);font-family:"Fraunces",serif;font-size:18px;font-weight:700}.profile-mini strong{display:block;font-size:14px}.profile-mini span span{display:block;margin-top:4px;color:rgba(22,35,30,.54);font-size:11px}.side-nav{display:grid;gap:6px;padding:16px 0}.side-nav a{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:14px;color:rgba(22,35,30,.64);font-size:13px;font-weight:650;transition:.2s ease}.side-nav a:hover{background:rgba(9,37,29,.06);color:var(--pine-900)}.side-nav a.active{background:var(--pine-900);color:#fff;box-shadow:0 14px 28px -22px rgba(6,26,21,.9)}.side-nav svg{width:18px;height:18px;flex:0 0 auto}.side-help{padding:15px;border-radius:18px;background:var(--oat)}.side-help strong{display:block;font-family:"Fraunces",serif;font-size:17px}.side-help p{margin:7px 0 12px;color:rgba(22,35,30,.6);font-size:11px;line-height:1.55}.side-help a{display:inline-flex;align-items:center;gap:6px;color:var(--pine-900);font-size:12px;font-weight:800}

    .content{min-width:0}.page-hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);min-height:300px;border-radius:34px;background:var(--pine-900);color:#fff;box-shadow:var(--shadow)}.hero-copy{position:relative;z-index:4;display:flex;flex-direction:column;justify-content:center;padding:42px 44px}.eyebrow{display:inline-flex;align-items:center;gap:8px;width:max-content;padding:7px 10px;border:1px solid rgba(223,252,98,.22);border-radius:999px;background:rgba(223,252,98,.08);color:var(--acid);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 7px rgba(223,252,98,.1)}.page-hero h1{margin:20px 0 12px;font-family:"Fraunces",serif;font-size:clamp(42px,5vw,70px);font-weight:600;letter-spacing:-.055em;line-height:.96}.page-hero h1 em{color:var(--acid);font-style:italic}.hero-copy>p{max-width:620px;margin:0;color:rgba(255,255,255,.66);font-size:15px;line-height:1.7}.hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 17px;border:0;border-radius:14px;cursor:pointer;font-size:13px;font-weight:800;transition:.22s ease}.btn-primary{background:var(--acid);color:var(--pine-950)}.btn-secondary{background:var(--oat);color:var(--pine-900)}.btn-ghost{border:1px solid rgba(255,255,255,.17);background:rgba(255,255,255,.07);color:#fff}.btn:hover{transform:translateY(-2px)}.hero-visual{position:relative;min-height:300px}.hero-photo{position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.14) 35%),url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=85") center/cover}.route-svg{position:absolute;inset:8%;z-index:2;width:84%;height:84%;filter:drop-shadow(0 0 8px rgba(223,252,98,.3))}.route-svg path{fill:none;stroke:var(--acid);stroke-width:2.5;stroke-linecap:round}.hero-pass{position:absolute;right:22px;bottom:22px;z-index:4;width:min(300px,calc(100% - 44px));padding:17px;border:1px solid rgba(255,255,255,.17);border-radius:20px;background:rgba(6,26,21,.75);backdrop-filter:blur(18px)}.hero-pass small{display:block;color:rgba(255,255,255,.48);font-size:9px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.hero-pass strong{display:block;margin-top:6px;font-family:"Fraunces",serif;font-size:19px}.hero-pass-row{display:flex;justify-content:space-between;gap:12px;margin-top:13px;padding-top:12px;border-top:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.64);font-size:10px}.hero-pass-row b{color:var(--acid)}

    .toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:18px 0 12px;padding:10px;border:1px solid var(--line);border-radius:20px;background:rgba(255,253,246,.8);box-shadow:var(--card-shadow);backdrop-filter:blur(16px)}.tabs{display:flex;gap:6px;overflow:auto;scrollbar-width:none}.tabs::-webkit-scrollbar{display:none}.tab{display:inline-flex;align-items:center;gap:7px;min-height:42px;padding:0 14px;border:0;border-radius:14px;background:transparent;color:rgba(22,35,30,.58);cursor:pointer;font-size:12px;font-weight:800;white-space:nowrap}.tab.active{background:var(--pine-900);color:#fff}.tab-count{display:grid;place-items:center;min-width:20px;height:20px;padding-inline:5px;border-radius:999px;background:rgba(9,37,29,.08);font-size:9px}.tab.active .tab-count{background:rgba(223,252,98,.17);color:var(--acid)}.toolbar-actions{display:flex;gap:8px;flex:0 0 auto}.icon-btn{display:grid;place-items:center;width:42px;height:42px;border:1px solid var(--line);border-radius:14px;background:var(--cream);color:var(--pine-900);cursor:pointer}.search-wrap{position:relative}.search{width:230px;height:42px;padding:0 42px 0 14px;border:1px solid var(--line);border-radius:14px;background:var(--cream);color:var(--ink);outline:none}.search:focus{border-color:var(--pine-700);box-shadow:0 0 0 4px rgba(27,82,66,.08)}.search-wrap svg{position:absolute;right:13px;top:12px;color:rgba(22,35,30,.4)}

    .ticket-stack{display:grid;gap:14px}.ticket-group{overflow:hidden;border:1px solid var(--line);border-radius:28px;background:var(--cream);box-shadow:var(--card-shadow)}.group-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:19px 21px;border-bottom:1px solid var(--line)}.group-kicker{margin:0 0 5px;color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.group-head h2{margin:0;font-family:"Fraunces",serif;font-size:25px;letter-spacing:-.025em}.group-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:7px;color:rgba(22,35,30,.52);font-size:10px}.group-status{display:inline-flex;align-items:center;gap:7px;padding:8px 10px;border-radius:999px;background:rgba(223,252,98,.28);color:var(--pine-800);font-size:9px;font-weight:900;white-space:nowrap}.group-status:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--pine-700)}.tickets-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:14px}.ticket-card{position:relative;overflow:hidden;min-width:0;border:1px solid rgba(9,37,29,.12);border-radius:23px;background:var(--oat);transition:.23s ease}.ticket-card:hover{transform:translateY(-3px);box-shadow:var(--card-shadow)}.ticket-card:before,.ticket-card:after{content:"";position:absolute;top:116px;z-index:2;width:22px;height:22px;border-radius:50%;background:var(--cream)}.ticket-card:before{left:-11px}.ticket-card:after{right:-11px}.ticket-top{position:relative;overflow:hidden;display:grid;grid-template-columns:1fr auto;gap:14px;min-height:126px;padding:18px;background:var(--pine-900);color:#fff}.ticket-top:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 85% 0,rgba(223,252,98,.18),transparent 27%);pointer-events:none}.ticket-person{position:relative;z-index:2}.ticket-person small{display:block;color:rgba(255,255,255,.46);font-size:8px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.ticket-person h3{margin:7px 0 5px;font-family:"Fraunces",serif;font-size:21px}.ticket-person p{margin:0;color:rgba(255,255,255,.6);font-size:9px}.ticket-index{position:relative;z-index:2;display:grid;place-items:center;width:44px;height:44px;border:1px solid rgba(223,252,98,.28);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid);font-family:"Fraunces",serif;font-size:18px}.ticket-cut{height:1px;margin:0 14px;border-top:1px dashed rgba(9,37,29,.2)}.ticket-body{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px;align-items:end;padding:17px 18px 18px}.ticket-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.fact small{display:block;color:rgba(22,35,30,.44);font-size:8px;font-weight:850;letter-spacing:.1em;text-transform:uppercase}.fact strong{display:block;margin-top:4px;font-size:11px}.ticket-actions{display:flex;gap:7px;align-items:center}.ticket-action{display:grid;place-items:center;width:39px;height:39px;border:1px solid var(--line);border-radius:13px;background:var(--cream);color:var(--pine-900);cursor:pointer}.ticket-action.primary{background:var(--acid);border-color:var(--acid)}.ticket-code{grid-column:1/-1;margin-top:1px;padding-top:11px;border-top:1px solid rgba(9,37,29,.1);color:rgba(22,35,30,.46);font-size:8px;font-weight:800;letter-spacing:.16em}

    .single-row{display:grid;grid-template-columns:140px minmax(0,1fr) auto;gap:16px;align-items:center;padding:14px}.single-visual{height:110px;border-radius:19px;background:linear-gradient(135deg,rgba(6,26,21,.05),rgba(223,252,98,.14)),url("https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?auto=format&fit=crop&w=700&q=82") center/cover}.single-copy small{color:var(--pine-700);font-size:8px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.single-copy h3{margin:6px 0 6px;font-family:"Fraunces",serif;font-size:22px}.single-copy p{margin:0;color:rgba(22,35,30,.55);font-size:10px;line-height:1.55}.single-copy .group-meta{margin-top:10px}.single-actions{display:flex;gap:8px}.used{opacity:.68;filter:saturate(.75)}.used .group-status{background:rgba(22,35,30,.07);color:rgba(22,35,30,.58)}.used .group-status:before{background:rgba(22,35,30,.35)}

    .empty{display:none;padding:70px 22px;text-align:center;border:1px dashed rgba(9,37,29,.2);border-radius:27px;background:rgba(255,253,246,.52)}.empty.visible{display:block}.empty-icon{display:grid;place-items:center;width:68px;height:68px;margin:0 auto 18px;border-radius:22px;background:var(--pine-900);color:var(--acid)}.empty h3{margin:0;font-family:"Fraunces",serif;font-size:29px}.empty p{max-width:450px;margin:10px auto 20px;color:rgba(22,35,30,.58);font-size:12px;line-height:1.65}

    .info-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:14px;margin-top:14px}.info-card{padding:22px;border:1px solid var(--line);border-radius:24px;background:var(--cream);box-shadow:var(--card-shadow)}.info-card.dark{position:relative;overflow:hidden;background:var(--pine-900);color:#fff}.info-card h3{margin:0;font-family:"Fraunces",serif;font-size:24px}.info-card p{margin:8px 0 0;color:rgba(22,35,30,.55);font-size:11px;line-height:1.65}.info-card.dark p{color:rgba(255,255,255,.58)}.guide-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:17px}.guide{padding:13px;border-radius:16px;background:var(--oat)}.guide strong{display:block;font-size:10px}.guide span{display:block;margin-top:5px;color:rgba(22,35,30,.5);font-size:8px;line-height:1.4}.wallet-card{position:relative;z-index:2;margin-top:17px;padding:17px;border:1px solid rgba(255,255,255,.13);border-radius:20px;background:rgba(255,255,255,.07)}.wallet-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.wallet-row strong{font-family:"Fraunces",serif;font-size:18px}.wallet-row span{color:var(--acid);font-size:9px;font-weight:900}.wallet-card button{width:100%;margin-top:14px}

    .modal{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:20px;background:rgba(6,26,21,.68);backdrop-filter:blur(13px);opacity:0;visibility:hidden;transition:.24s ease}.modal.open{opacity:1;visibility:visible}.modal-card{position:relative;width:min(460px,100%);max-height:min(760px,calc(100dvh - 28px));overflow:auto;padding:26px;border-radius:29px;background:var(--cream);box-shadow:0 40px 100px -30px rgba(0,0,0,.68);transform:translateY(14px) scale(.98);transition:.24s ease}.modal.open .modal-card{transform:none}.modal-close{position:absolute;right:14px;top:14px;display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:13px;background:var(--oat);cursor:pointer}.modal-kicker{color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.modal h3{margin:8px 0 7px;padding-right:45px;font-family:"Fraunces",serif;font-size:29px}.modal p{margin:0;color:rgba(22,35,30,.58);font-size:11px;line-height:1.6}.digital-pass{margin-top:19px;padding:19px;border-radius:23px;background:var(--pine-900);color:#fff}.digital-head{display:flex;justify-content:space-between;gap:12px}.digital-head small{display:block;color:rgba(255,255,255,.46);font-size:8px;letter-spacing:.14em;text-transform:uppercase}.digital-head strong{display:block;margin-top:5px;font-family:"Fraunces",serif;font-size:19px}.qr-large{width:170px;height:170px;margin:23px auto;background:repeating-conic-gradient(#09251d 0 25%,#fff 0 50%) 0 0/14px 14px,linear-gradient(#fff,#fff);border:14px solid #fff;box-shadow:0 0 0 1px rgba(255,255,255,.15),0 18px 40px -25px rgba(0,0,0,.7)}.digital-code{text-align:center;color:var(--acid);font-size:10px;font-weight:900;letter-spacing:.18em}.modal-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}.share-fields{display:grid;gap:10px;margin-top:18px}.field{height:48px;padding:0 14px;border:1px solid var(--line);border-radius:14px;background:var(--oat);outline:none}.field:focus{border-color:var(--pine-700);box-shadow:0 0 0 4px rgba(27,82,66,.08)}

    .toast{position:fixed;right:20px;bottom:20px;z-index:120;display:flex;align-items:center;gap:10px;max-width:360px;padding:14px 16px;border-radius:16px;background:var(--pine-900);color:#fff;box-shadow:0 30px 70px -30px rgba(0,0,0,.78);transform:translateY(20px);opacity:0;pointer-events:none;transition:.25s ease}.toast.show{transform:none;opacity:1}.toast-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:10px;background:rgba(223,252,98,.14);color:var(--acid)}.toast strong{display:block;font-size:11px}.toast span{display:block;margin-top:3px;color:rgba(255,255,255,.55);font-size:9px}

    .mobile-nav{display:none}.mobile-menu{position:fixed;inset:0;z-index:90;padding:16px;background:var(--pine-950);color:#fff;transform:translateX(100%);transition:.3s cubic-bezier(.22,.8,.2,1)}.mobile-menu.open{transform:none}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:8px;margin-top:34px}.mobile-menu-links a{padding:16px;border-bottom:1px solid rgba(255,255,255,.1);font-family:"Fraunces",serif;font-size:27px}

    @media(max-width:1180px){.layout{grid-template-columns:220px minmax(0,1fr)}.page-hero{grid-template-columns:1fr minmax(280px,.75fr)}.search{width:190px}}
    @media(max-width:980px){.main-nav{display:none}.menu-btn{display:grid}.layout{grid-template-columns:1fr;padding-top:10px}.sidebar{display:none}.page-hero{grid-template-columns:1fr}.hero-copy{padding-bottom:24px}.hero-visual{min-height:260px}.tickets-grid{grid-template-columns:1fr}.info-grid{grid-template-columns:1fr}.toolbar{position:sticky;top:78px;z-index:20}.single-row{grid-template-columns:120px 1fr auto}}
