  <div class="mobile-menu" id="mobileMenu" aria-hidden="true"><div class="mobile-menu-head"><a class="brand" href="/"><span class="brand-mark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/></svg></span><span class="brand-copy"><strong>Nordvale</strong><span>Wild Park & Forest Reserve</span></span></a><button class="menu-btn" id="menuClose" type="button" aria-label="Închide meniul"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="mobile-menu-links"><a href="/experiente">Experiențe</a><a href="/planifica">Planifică vizita</a><a href="/calendar">Calendar</a><a href="/bilete">Bilete</a><a href="/autentificare">Deconectare</a></div></div>

  <div class="modal" id="ticketModal" aria-hidden="true"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="ticketModalTitle"><button class="modal-close" type="button" data-close-modal aria-label="Închide"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button><span class="modal-kicker">Acces individual</span><h3 id="ticketModalTitle">Bilet pentru <span id="modalTicketName">Andrei Popescu</span></h3><p>Prezintă codul la Poarta Nord. Fiecare participant trebuie scanat separat.</p><div class="digital-pass"><div class="digital-head"><span><small>Canopy Run Day</small><strong id="modalParticipant">Andrei Popescu</strong></span><span><small>Bilet</small><strong id="modalIndex">01 / 04</strong></span></div><div class="qr-large" aria-label="Cod QR demonstrativ"></div><div class="digital-code" id="modalCode">NV-1842-A01</div></div><div class="modal-actions"><button class="btn btn-primary" type="button" data-wallet>Adaugă în Wallet</button><button class="btn btn-secondary" type="button" data-download>Descarcă PDF</button></div></div></div>

  <div class="modal" id="shareModal" aria-hidden="true"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="shareModalTitle"><button class="modal-close" type="button" data-close-modal aria-label="Închide"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button><span class="modal-kicker">Distribuire bilet</span><h3 id="shareModalTitle">Trimite accesul pentru <span id="shareTicketName">participant</span></h3><p>Destinatarul va primi un link securizat și propriul cod QR. Biletul rămâne vizibil și în contul tău.</p><form id="shareForm"><div class="share-fields"><input class="field" id="shareEmail" type="email" placeholder="email@exemplu.ro" required><input class="field" id="shareMessage" type="text" placeholder="Mesaj opțional"></div><button class="btn btn-primary" type="submit" style="width:100%;margin-top:12px">Trimite biletul</button></form></div></div>

  <div class="toast" id="toast" role="status"><span class="toast-icon"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4 10-10"/></svg></span><span><strong id="toastTitle">Gata</strong><span id="toastText">Acțiunea a fost finalizată.</span></span></div>

  <script>
    (()=>{
      'use strict';
      const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
      const body=document.body, menu=$('#mobileMenu'), ticketModal=$('#ticketModal'), shareModal=$('#shareModal'), toast=$('#toast');
      const openMenu=()=>{menu?.classList.add('open');menu?.setAttribute('aria-hidden','false');body.style.overflow='hidden'};
      const closeMenu=()=>{menu?.classList.remove('open');menu?.setAttribute('aria-hidden','true');body.style.overflow=''};
      $('#menuOpen')?.addEventListener('click',openMenu);$('#menuClose')?.addEventListener('click',closeMenu);
      const openModal=modal=>{modal?.classList.add('open');modal?.setAttribute('aria-hidden','false');body.style.overflow='hidden'};
      const closeModal=modal=>{modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');body.style.overflow=''};
      $$('[data-close-modal]').forEach(btn=>btn.addEventListener('click',()=>closeModal(btn.closest('.modal'))));
      $$('.modal').forEach(modal=>modal.addEventListener('click',e=>{if(e.target===modal)closeModal(modal)}));
      document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();$$('.modal.open').forEach(closeModal)}});
      const showToast=(title,text)=>{if(!toast)return;$('#toastTitle').textContent=title;$('#toastText').textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),3000)};
      $$('[data-open-ticket]').forEach(btn=>btn.addEventListener('click',()=>{const name=btn.dataset.ticketName||'Andrei Popescu',index=btn.dataset.ticketIndex||'1';$('#modalTicketName').textContent=name;$('#modalParticipant').textContent=name;$('#modalIndex').textContent=index==='M'?'MEMBRU':`${String(index).padStart(2,'0')} / 04`;$('#modalCode').textContent=index==='M'?'NV-WC-2039':`NV-1842-${Number(index)<=2?'A':'C'}${String(index).padStart(2,'0')}`;openModal(ticketModal)}));
      $$('[data-share]').forEach(btn=>btn.addEventListener('click',()=>{$('#shareTicketName').textContent=btn.dataset.ticketName||'participant';openModal(shareModal)}));
      $('#shareForm')?.addEventListener('submit',e=>{e.preventDefault();const email=$('#shareEmail').value.trim();if(!email)return;closeModal(shareModal);e.target.reset();showToast('Bilet trimis',`Linkul securizat a fost trimis la ${email}.`)});
      $$('[data-wallet]').forEach(btn=>btn.addEventListener('click',()=>showToast('Adăugat în Wallet','Biletul este disponibil și offline.')));
      $$('[data-download]').forEach(btn=>btn.addEventListener('click',()=>showToast('PDF pregătit','Fișierul demonstrativ a fost generat.')));
      $('#downloadAll')?.addEventListener('click',()=>showToast('Bilete pregătite','Arhiva cu toate biletele a fost generată.'));
      $('#walletAll')?.addEventListener('click',()=>showToast('Wallet actualizat','Toate cele 4 bilete au fost adăugate.'));
      $('#notificationButton')?.addEventListener('click',()=>showToast('Notificări','Nu ai notificări noi despre bilete.'));

      let activeFilter='active', sortDesc=false;
      const groups=$$('.ticket-group'), empty=$('#emptyState'), search=$('#ticketSearch');
      const applyFilters=()=>{const q=(search?.value||'').trim().toLowerCase();let visible=0;groups.forEach(group=>{const matchesCategory=group.dataset.category===activeFilter;const matchesSearch=!q||(group.dataset.search||'').includes(q);const show=matchesCategory&&matchesSearch;group.hidden=!show;if(show)visible++});empty?.classList.toggle('visible',visible===0)};
      $$('.tab').forEach(tab=>tab.addEventListener('click',()=>{$$('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');activeFilter=tab.dataset.filter;applyFilters()}));
      search?.addEventListener('input',applyFilters);
      $('#sortButton')?.addEventListener('click',()=>{sortDesc=!sortDesc;const stack=$('#ticketStack');const visible=groups.filter(g=>!g.hidden).reverse();visible.forEach(g=>stack?.appendChild(g));showToast('Ordine schimbată',sortDesc?'Cele mai îndepărtate apar primele.':'Cele mai apropiate apar primele.')});

      if(!matchMedia('(prefers-reduced-motion: reduce)').matches){
        $$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:620,delay:70+i*75,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));
        const route=$('#heroRoute');if(route){const length=route.getTotalLength();route.style.strokeDasharray=length;route.style.strokeDashoffset=length;route.animate([{strokeDashoffset:length},{strokeDashoffset:0}],{duration:1700,delay:250,easing:'cubic-bezier(.22,.8,.2,1)',fill:'forwards'})}
        const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:520,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});observer.unobserve(entry.target)}}),{threshold:.1});$$('.ticket-group,.info-card').forEach(el=>observer.observe(el));
      }
      applyFilters();
    })();
  </script>
  <script>
  (function(){
    function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
    var a = nvAuth();
    if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
    var AH = { 'Authorization':'Bearer '+a.token };
    function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
    function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
    function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }
    function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
    function fmtDate(iso){ if(!iso)return ''; var d=new Date(iso); if(isNaN(d))return ''; return d.toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'}); }
    function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; var em=box.querySelector('strong + span'); if(em&&u.email)em.textContent=u.email; } }
    document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
    hydrateUser(a.user);
    api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

    function drawQR(el,code){ if(!el||!window.QRCode)return; el.innerHTML=''; var cv=document.createElement('canvas'); el.appendChild(cv); window.QRCode.toCanvas(cv, code||' ', {width:160,margin:1}, function(){}); }
    function openTicketModal(code,event){ var m=document.querySelector('#ticketModal'); if(!m)return; var nm=window.__nvName||'Bilet'; var q1=document.querySelector('#modalTicketName'); if(q1)q1.textContent=event||nm; var q2=document.querySelector('#modalParticipant'); if(q2)q2.textContent=nm; var q3=document.querySelector('#modalIndex'); if(q3)q3.textContent='BILET'; var q4=document.querySelector('#modalCode'); if(q4)q4.textContent=code||''; drawQR(m.querySelector('.qr-large'),code); m.classList.add('open'); m.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }

    api('acc-tickets').then(function(d){ if(!(d&&d.success&&d.data))return; var up=d.data.upcoming||[]; var past=d.data.past||[]; if(!up.length&&!past.length)return; var nm=window.__nvName||'Bilet';
      function grp(t,cat){ var meta=[t.date?fmtDate(t.date):'', t.time?String(t.time).slice(0,5):'', t.venue||''].filter(Boolean).join(' · '); var code=t.code||'';
        return '<article class="ticket-group'+(cat==='used'?' used':'')+'" data-category="'+cat+'" data-search="'+esc(((t.event||'')+' '+code+' '+(t.venue||'')).toLowerCase())+'">'
         +'<header class="group-head"><span><p class="group-kicker">'+esc(t.is_subscription?'Acces abonament':'Bilet')+'</p><h2>'+esc(t.event||'Experiență Nordvale')+'</h2><span class="group-meta">'+(meta?('<span>'+esc(meta)+'</span>'):'')+'</span></span><span class="group-status">'+(cat==='used'?'Utilizat':'Activ')+'</span></header>'
         +'<div class="single-row"><div class="single-visual"></div><div class="single-copy"><small>'+esc(t.seat_label||t.type||'Acces')+'</small><h3>'+esc(nm)+'</h3><p>Cod bilet '+esc(code)+'.</p></div><div class="single-actions"><button class="btn btn-primary" type="button" data-nv-open data-code="'+esc(code)+'" data-event="'+esc(t.event||'')+'">Deschide QR</button></div></div></article>'; }
      var html=up.map(function(t){return grp(t,'active');}).join('')+past.map(function(t){return grp(t,'used');}).join('');
      var stack=document.querySelector('#ticketStack'); if(!stack)return; stack.innerHTML=html;
      var counts=document.querySelectorAll('.tab .tab-count'); if(counts[0])counts[0].textContent=up.length; if(counts[1])counts[1].textContent=0; if(counts[2])counts[2].textContent=past.length;
      var groups=[].slice.call(stack.querySelectorAll('.ticket-group')); var empty=document.querySelector('#emptyState'); var af='active'; var searchEl=document.querySelector('#ticketSearch');
      function apply(){ var q=((searchEl&&searchEl.value)||'').trim().toLowerCase(); var vis=0; groups.forEach(function(gr){ var mc=gr.dataset.category===af; var ms=!q||(gr.dataset.search||'').indexOf(q)>=0; var show=mc&&ms; gr.hidden=!show; if(show)vis++; }); if(empty)empty.classList.toggle('visible',vis===0); }
      document.querySelectorAll('.tab').forEach(function(t){ var cl=t.cloneNode(true); t.parentNode.replaceChild(cl,t); cl.addEventListener('click',function(){ document.querySelectorAll('.tab').forEach(function(x){x.classList.remove('active');}); cl.classList.add('active'); af=cl.dataset.filter; apply(); }); });
      if(searchEl){ var c2=searchEl.cloneNode(true); searchEl.parentNode.replaceChild(c2,searchEl); searchEl=c2; searchEl.addEventListener('input',apply); }
      var sb=document.querySelector('#sortButton'); if(sb){ var scb=sb.cloneNode(true); sb.parentNode.replaceChild(scb,sb); scb.addEventListener('click',function(){ var vis=groups.filter(function(g){return !g.hidden;}).reverse(); vis.forEach(function(g){ stack.appendChild(g); }); }); }
      stack.querySelectorAll('[data-nv-open]').forEach(function(b){ b.addEventListener('click',function(){ openTicketModal(b.dataset.code,b.dataset.event); }); });
      apply();
      var hero=document.querySelector('.hero-actions [data-open-ticket]'); if(hero&&up[0]){ hero.addEventListener('click',function(){ openTicketModal(up[0].code,up[0].event); }); }
    });
  })();
  </script>
</body>
</html>
